let builtinSc=null;
function builtinKickOrSnare(fv){
  if(!builtinSc){ const all=[...BUILTIN_DRUMS.kick,...BUILTIN_DRUMS.snare], D=all[0].length, sd=[];
    for(let d=0;d<D;d++){ const m=all.reduce((a,v)=>a+v[d],0)/all.length; sd.push(Math.sqrt(all.reduce((a,v)=>a+(v[d]-m)**2,0)/all.length)||1); }
    const W=sd.map((_,d)=>d<24?1:[1.5,3,2,3,2][d-24]||1), fl=median(sd)*0.35; builtinSc=sd.map((v,d)=>Math.max(v,fl)/W[d]); }
  return nearestSlot(fv,[{id:'kick',ex:BUILTIN_DRUMS.kick},{id:'snare',ex:BUILTIN_DRUMS.snare}],builtinSc).id; }
function ruleClassify(ons){
  const rest=[];
  ons.forEach(o=>{ if(o.low>0.45||o.cen<850) o.cls='kick'; else rest.push(o); });
  if(rest.length){
    let others=rest;
    const bg=widestGap(rest.map(o=>Math.log2(o.cen)));
    const upper=rest.filter(o=>Math.log2(o.cen)>bg.cut);
    if(bg.g>0.6 && median(upper.map(o=>o.cen))>5000){ upper.forEach(o=>o.cls='hat'); others=rest.filter(o=>!upper.includes(o)); }
    else { others=[]; rest.forEach(o=>{ const n=nearestProto(o,['clap','snare','hat']); if(n==='hat') o.cls='hat'; else others.push(o); }); }
    if(others.length){ const dg=widestGap(others.map(o=>Math.log2(o.dur)));
      if(others.length>1 && dg.g>0.9) others.forEach(o=>o.cls=Math.log2(o.dur)<dg.cut?'clap':'snare');
      else others.forEach(o=>o.cls=nearestProto(o,['clap','snare'])); }
  }
  // hi-hats and claps stay with the rules (a sharp "k" is how Noodle asks for a clap); between kick and snare,
  // the built-in examples decide
  ons.forEach(o=>{ if(o.fv && o.fv.length===BUILTIN_DRUMS.kick[0].length && (o.cls==='kick'||o.cls==='snare')) o.cls=builtinKickOrSnare(o.fv); });
  // the rules name the four default sounds; send them to whichever slot plays that sound now
  ons.forEach(o=>{ if(!slotOf(o.cls)){ const sl=S.kit.slots.find(x=>x.sound===o.cls); if(sl) o.cls=sl.id; } });
}
/* Pitch tracking (YIN at 16 kHz) and note segmentation */
/* Whistles sit at 1-4 kHz, far above humming, and are nearly pure tones: follow the strongest spectral peak. */
function whistleFrames(x, sr){
  const N=2048, hop=Math.round(sr*0.01), f=getFFT(N), w=f.win, re=new Float32Array(N), im=new Float32Array(N);
  const k0=Math.floor(500*N/sr), k1=Math.ceil(4500*N/sr), kA=Math.floor(300*N/sr), kB=Math.ceil(8000*N/sr), out=[];
  for(let s0=0;s0+N<x.length;s0+=hop){
    let e=0; for(let i=0;i<N;i++){ const v=x[s0+i]; re[i]=v*w[i]; im[i]=0; e+=v*v; } f(re,im);
    let pk=k0, pv=0, tot=1e-12; const P=k=>re[k]*re[k]+im[k]*im[k];
    for(let k=kA;k<kB;k++){ const pw=P(k); tot+=pw; if(k>=k0&&k<=k1&&pw>pv){pv=pw;pk=k;} }
    const a=Math.log(P(pk-1)+1e-12), b=Math.log(pv+1e-12), c=Math.log(P(pk+1)+1e-12), den=a-2*b+c, dl=Math.abs(den)>1e-9?0.5*(a-c)/den:0;
    const hz=(pk+dl)*sr/N, tonal=(P(pk-1)+pv+P(pk+1))/tot;
    out.push({t:(s0+N/2)/sr, db:10*Math.log10(e/N+1e-12), conf:tonal>0.55?0.05:1, m:69+12*Math.log2(hz/440), hz});
  }
  return out;
}
